INSERT IGNORE INTO `automation_rules` (`id`,`code`,`name`,`description`,`phase`,`trigger_type`,`trigger_json`,`conditions_json`,`actions_json`,`project_types`,`status`,`created_by`,`updated_by`,`created_at`,`updated_at`,`last_run_at`) VALUES
('92273013-6fa3-5c81-aa31-11537d765023','PAYMENT_OVERDUE_ALERT','Payment milestone overdue','Tells accounts and the project manager the day a client milestone goes past due.','Finance','PAYMENT_MILESTONE_OVERDUE','{"params": {"graceDays": 0, "cooldownHours": 72}}','[]','[{"type": "NOTIFY", "recipient": "accounts", "title": "Payment overdue — {{projectName}}", "message": "{{title}}: {{outstanding}} outstanding, {{daysOverdue}} days past due."}, {"type": "NOTIFY", "recipient": "project_manager", "title": "Payment overdue — {{projectName}}", "message": "{{title}} is {{daysOverdue}} days late ({{outstanding}})."}]','[]','ACTIVE','2d177b4b-aed4-5e59-bc98-2087257aa8dc','2d177b4b-aed4-5e59-bc98-2087257aa8dc','2026-08-21 11:00:00','2026-08-23 15:00:00','2026-09-28 09:30:00'),
('f2d238df-01be-5c23-b8e2-98f70b384d36','PAYMENT_OVERDUE_15D_ESCALATE','Payment overdue 15+ days','Escalates to the founders and opens a follow-up task for accounts.','Finance','PAYMENT_MILESTONE_OVERDUE','{"params": {"graceDays": 0, "cooldownHours": 168}}','[{"field": "daysOverdue", "operator": "greater_than", "value": "15"}]','[{"type": "ESCALATE", "recipient": "admins", "priority": "HIGH", "title": "{{projectName}}: {{title}} unpaid for {{daysOverdue}} days"}, {"type": "TASK", "recipient": "accounts", "priority": "high", "dueInDays": 2, "title": "Call client about {{title}} ({{projectName}})", "message": "{{outstanding}} outstanding since {{dueDate}}."}]','[]','ACTIVE','c4af5469-bbd1-11f1-9c80-02fc00000001','c4af5469-bbd1-11f1-9c80-02fc00000001','2026-08-26 11:00:00','2026-08-28 15:00:00','2026-09-28 09:30:00'),
('287b4b12-0da2-596a-9042-50a0685141a9','PHASE_STALLED_21D','Project phase stalled 3 weeks','Flags active projects that have not cleared a gate or moved phase in 21 days.','Projects','PHASE_STALLED','{"params": {"days": 21, "cooldownHours": 168}}','[]','[{"type": "NOTIFY", "recipient": "project_manager", "title": "{{projectName}} has not moved in {{daysInPhase}} days", "message": "Still in {{currentPhase}}. Check what is blocking the next gate."}, {"type": "TASK", "recipient": "project_manager", "priority": "medium", "dueInDays": 3, "title": "Unblock {{projectName}} ({{currentPhase}})"}]','[]','ACTIVE','5b21e83f-240f-538a-8681-19997edc9c48','5b21e83f-240f-538a-8681-19997edc9c48','2026-08-31 11:00:00','2026-09-02 15:00:00','2026-09-28 09:30:00'),
('e1c3a329-cb76-54aa-b7e4-f43c7f5c1a2c','PHASE_STALLED_CRITICAL','Critical project stalled','Escalates high-priority projects stuck for 30+ days.','Projects','PHASE_STALLED','{"params": {"days": 30, "cooldownHours": 336}}','[{"field": "priority", "operator": "in", "value": "HIGH,CRITICAL"}]','[{"type": "ESCALATE", "recipient": "admins", "priority": "CRITICAL", "title": "{{projectName}} stuck in {{currentPhase}} for {{daysInPhase}} days"}]','[]','ACTIVE','c4af5469-bbd1-11f1-9c80-02fc00000001','c4af5469-bbd1-11f1-9c80-02fc00000001','2026-09-02 11:00:00','2026-09-04 15:00:00','2026-09-28 09:30:00'),
('3020856f-3b4c-55d3-a84c-6b91aba7b673','QC_FAILED_CORRECTIVE','QC failed — corrective task','Creates a corrective task for site and alerts the PM when an inspection fails.','Site operations','QC_FAILED','{"params": {"lookbackDays": 30, "cooldownHours": 720}}','[]','[{"type": "TASK", "recipient": "site_engineer", "priority": "high", "dueInDays": 3, "title": "Corrective work: {{stepName}} at {{projectName}}", "message": "QC {{result}} on attempt {{attemptNumber}} (checked by {{checkedBy}})."}, {"type": "NOTIFY", "recipient": "project_manager", "title": "QC {{result}}: {{stepName}}", "message": "{{projectName}} — corrective task raised for site."}]','[]','ACTIVE','5b21e83f-240f-538a-8681-19997edc9c48','5b21e83f-240f-538a-8681-19997edc9c48','2026-09-05 11:00:00','2026-09-07 15:00:00','2026-09-28 09:30:00'),
('5f11d9fc-0d86-58c0-aacb-dcc35a4f6cac','RFI_OVERDUE_24H','RFI unanswered 24 hours','Escalates site RFIs with no response after 24 hours.','Site operations','RFI_OVERDUE','{"params": {"hours": 24, "cooldownHours": 24}}','[]','[{"type": "NOTIFY", "recipient": "designer", "title": "RFI waiting {{ageHours}} h — {{projectName}}", "message": "{{entity_label}}"}, {"type": "ESCALATE", "recipient": "project_manager", "priority": "HIGH", "title": "{{entity_label}} unanswered ({{projectName}})"}]','[]','ACTIVE','5b21e83f-240f-538a-8681-19997edc9c48','5b21e83f-240f-538a-8681-19997edc9c48','2026-09-08 11:00:00','2026-09-10 15:00:00','2026-09-28 09:30:00'),
('872818c2-a7a6-53f1-b6a3-1a7d3c5bdfd1','TASK_OVERDUE_NUDGE','Task overdue nudge','Reminds the assignee one day after a task''s due date.','Execution','TASK_OVERDUE','{"params": {"graceDays": 1, "cooldownHours": 72}}','[{"field": "priority", "operator": "in", "value": "high,critical"}]','[{"type": "NOTIFY", "recipient": "assignee", "title": "Overdue: {{title}}", "message": "{{projectName}} — {{daysOverdue}} days past due."}]','[]','DRAFT','5b21e83f-240f-538a-8681-19997edc9c48','5b21e83f-240f-538a-8681-19997edc9c48','2026-09-24 11:00:00','2026-09-26 15:00:00',NULL);
